-- Example of the OLD SK Arabians portal database (for testing tools/import_old.php). Not real data.
SET NAMES utf8mb4;
CREATE TABLE roles (id INT PRIMARY KEY, role_name VARCHAR(50), permissions TEXT);
CREATE TABLE users (id INT PRIMARY KEY, username VARCHAR(50), full_name VARCHAR(100), email VARCHAR(100), password VARCHAR(255), role_id INT, is_active TINYINT, last_login DATETIME, created_at DATETIME);
CREATE TABLE horses (id INT PRIMARY KEY, horse_name VARCHAR(100), arabic_name VARCHAR(100), date_of_birth VARCHAR(20), gender VARCHAR(10), category VARCHAR(20), color VARCHAR(30), breed VARCHAR(40), sire VARCHAR(100), dam VARCHAR(100), microchip VARCHAR(40), reg_no VARCHAR(40), status VARCHAR(20), shelter VARCHAR(40), purchase_price DECIMAL(12,2), notes TEXT, created_at DATETIME);
CREATE TABLE embryos (id INT PRIMARY KEY, embryo_code VARCHAR(20), dam_name VARCHAR(100), sire_name VARCHAR(100), collection_date DATE, date_of_birth DATE, status VARCHAR(20), grade VARCHAR(10), shelter VARCHAR(40), recipient VARCHAR(100), notes TEXT);
CREATE TABLE employees (id INT PRIMARY KEY, name VARCHAR(100), position VARCHAR(60), nationality VARCHAR(40), phone VARCHAR(30), email VARCHAR(100), qid VARCHAR(20), qid_expiry DATE, passport_no VARCHAR(20), passport_expiry DATE, basic_salary DECIMAL(10,2), allowances DECIMAL(10,2), joining_date DATE, status VARCHAR(20), show_on_website TINYINT DEFAULT 0);
CREATE TABLE categories (id INT PRIMARY KEY, name VARCHAR(60), type VARCHAR(20));
CREATE TABLE currencies (id INT PRIMARY KEY, code VARCHAR(3), name VARCHAR(40), rate DECIMAL(12,6), updated_at DATETIME);
CREATE TABLE currency_history (id INT PRIMARY KEY, currency_code VARCHAR(3), rate DECIMAL(12,6), created_at DATETIME);
CREATE TABLE transactions (id INT PRIMARY KEY, bill_no VARCHAR(30), type VARCHAR(20), category_id INT, description VARCHAR(255), amount DECIMAL(14,5), currency VARCHAR(3), exchange_rate DECIMAL(12,6), amount_usd DECIMAL(16,5), bill_date DATE, due_date DATE, status VARCHAR(20), supplier VARCHAR(100), horse_id INT, payment_method VARCHAR(30), created_by INT);
CREATE TABLE inventories (id INT PRIMARY KEY, name VARCHAR(60), category VARCHAR(30));
CREATE TABLE inventory_items (id INT PRIMARY KEY, inventory_id INT, item_name VARCHAR(100), unit VARCHAR(20), qty DECIMAL(10,2), unit_price DECIMAL(10,2), min_qty DECIMAL(10,2), expiry_date DATE, supplier VARCHAR(100));
CREATE TABLE activity_log (id INT PRIMARY KEY, user_id INT, action VARCHAR(50), created_at DATETIME);
